'use strict';
const LifeUI=(()=>{
  let selected='carrot';const names={carrot:'몽글당근',cotton:'폭신목화',butterfly:'나비',dragonfly:'잠자리',chest:'보물상자',moonDust:'달빛 마법 가루'};
  const game=document.querySelector('.game');
  const panel=document.createElement('div');panel.className='glass seed-picker';panel.innerHTML='<b>오늘의 씨앗</b><button data-seed="carrot" aria-pressed="true">🥕 당근 · 10 조개 / 15초</button><button data-seed="cotton" aria-pressed="false">☁ 목화 · 20 조개 / 30초</button><small>밭 칸 터치 → 심기 · 익으면 수확</small>';game.append(panel);
  panel.querySelectorAll('[data-seed]').forEach(b=>b.onclick=()=>{selected=b.dataset.seed;panel.querySelectorAll('button').forEach(a=>a.setAttribute('aria-pressed',String(a===b)))});
  const plots=[];for(let r=0;r<3;r++)for(let col=0;col<5;col++){const i=r*5+col,x=971+col*24+r*27,y=548-col*8+r*18;const b=document.createElement('button');b.className='plot-hit';b.style.left=x/16+'%';b.style.top=y/9+'%';b.onclick=()=>{const p=economy.plot(i);if(p.stage==='growing')return toast(`${LifeEconomy.crops[p.crop].name} · ${p.remaining}초 후 수확`);const result=p.stage==='ready'?economy.harvest(i):economy.plant(i,selected);toast(result.message+(economy.storageOK?'':' · 저장 불가: 이번 방문에만 유지'));refresh()};game.append(b);plots.push(b)}
  const fishButton=document.createElement('button');fishButton.className='world-label fishing-label';fishButton.textContent='≈ 바닷가 낚시';fishButton.onclick=openFishing;game.append(fishButton);
  const bugs=[{kind:'butterfly',baseX:870,baseY:430,phase:0},{kind:'dragonfly',baseX:660,baseY:580,phase:2},{kind:'butterfly',baseX:940,baseY:480,phase:4}].map((bug,i)=>{const b=document.createElement('button');b.className='bug '+bug.kind;b.setAttribute('aria-label',bug.kind==='butterfly'?'나비 잡기':'잠자리 잡기');b.textContent=bug.kind==='butterfly'?'🦋':'✣';game.append(b);bug.button=b;bug.available=0;b.onclick=()=>{if(Date.now()<bug.available)return;bug.available=Date.now()+12000;b.hidden=true;economy.catchBug(bug.kind);toast(`${names[bug.kind]} +1 · 조개 +${bug.kind==='butterfly'?15:25}`)};return bug});
  function bag(){const d=economy.data;modal('나의 작은 가방',`<p>농장과 바다에서 모은 소중한 것들이에요.</p><div class="cards" id="resourceBag">${Object.keys(names).map(k=>`<div class="item">${names[k]} <b data-resource="${k}">${d.inventory[k]}</b></div>`).join('')}</div><p>조개 <b id="bagShells">${d.shells.toLocaleString()}</b> · 씨앗은 심을 때 조개로 구매해요.</p><p>폭신목화는 공방용 원단 재료, 보물상자는 보관 아이템입니다.</p>`)}
  function refresh(){const d=economy.data;state.shells=d.shells;state.harvest=d.inventory.carrot;$('#shells').textContent=d.shells.toLocaleString();$('#currency').setAttribute('aria-label',`보유 조개 ${d.shells.toLocaleString()}개`);$('#progress').textContent=`${Math.min(3,d.carrotsHarvested)} / 3`;$('#questbar').style.width=Math.min(100,d.carrotsHarvested/3*100)+'%';let ready=0;plots.forEach((b,i)=>{const p=economy.plot(i);if(p.stage==='ready')ready++;b.classList.toggle('ready',p.stage==='ready');b.classList.toggle('growing',p.stage==='growing');b.textContent=p.stage==='ready'?'✦':p.stage==='growing'?'•':'+';b.setAttribute('aria-label',`밭 ${i+1}: ${p.stage==='empty'?`빈 밭, ${LifeEconomy.crops[selected].name} 심기`:LifeEconomy.crops[p.crop].name+(p.stage==='ready'?' 수확하기':` ${p.remaining}초 남음`)}`);b.title=b.getAttribute('aria-label')});$('#farm').innerHTML=`♧ 몽글 텃밭 <span>${ready?ready+'칸 수확 가능':'씨앗을 심어 보세요'}</span>`;document.querySelectorAll('[data-resource]').forEach(b=>b.textContent=d.inventory[b.dataset.resource]);if($('#bagShells'))$('#bagShells').textContent=d.shells.toLocaleString()}
  function openFishing(){modal('바닷가 타이밍 낚시','<p>낚싯대를 던진 뒤, 움직이는 표시가 초록 구간 안에 오면 낚아채세요. 제한 시간은 8초예요.</p><div class="fishing-track"><span class="fishing-zone"></span><i id="fishCursor"></i></div><p id="fishStatus" role="status">성공하면 조개 80개 또는 보물상자를 얻어요.</p><button class="primary" id="castFish">낚싯대 던지기</button><button class="primary" id="reelFish" disabled>지금 낚아채기!</button>');$('#castFish').onclick=()=>{if(economy.startFishing()){$('#castFish').disabled=true;$('#reelFish').disabled=false;$('#reelFish').focus()}};$('#reelFish').onclick=()=>finishFishing();}
  function finishFishing(){const result=economy.reel();if($('#fishStatus')){$('#fishStatus').textContent=result.message;$('#castFish').disabled=false;$('#castFish').textContent='다시 던지기';$('#reelFish').disabled=true}}
  $('#modal').addEventListener('close',()=>economy.cancelFishing());
  function frame(t){bugs.forEach(b=>{b.button.hidden=Date.now()<b.available;b.button.style.left=(b.baseX+Math.sin(t/1800+b.phase)*90)/16+'%';b.button.style.top=(b.baseY+Math.cos(t/1300+b.phase)*35)/9+'%'});const f=economy.fishingState();if(f&&$('#fishCursor')){$('#fishCursor').style.left=f.position*100+'%';$('#fishStatus').textContent=`${f.remaining}초 · 초록 구간에 맞춰 낚아채세요!`;if(f.expired)finishFishing()}requestAnimationFrame(frame)}
  economy.subscribe(refresh);refresh();setInterval(refresh,500);requestAnimationFrame(frame);
  return {bag};
})();
